from pathlib import Path
import datetime,hashlib,json,subprocess
import fitz
R=Path('/workspace/nonarchimedean-pluripotential-theory');M=R/'manuscript';C=R/'source_material/Segre_finite_pullback_sources_20261007'
h=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
read=lambda p:json.loads(Path(p).read_text())
git=lambda *a:subprocess.check_output(['git',*a],cwd=R,text=True).strip()
pin=lambda p:{'path':str(p),'bytes':p.stat().st_size,'sha256':h(p)}
bp=C/'baseline_v1_20261007.json';assert h(bp)=='7655aced35f8e0574fbd65b6cf585c8390e00de33434fa05a1d547bfef6c4b0d';b=read(bp)
out=M/'editorial/Segre_finite_pullback_source_review_manifest_20261007.json';assert not out.exists()
assert git('rev-parse','HEAD')==git('rev-parse','origin/work')==b['baseline_commit']
assert not git('diff','--cached','--name-only')
for p,sha in b['tracked_file_hashes'].items():assert h(R/p)==sha,(p,'tracked changed before source checkpoint')
for key in ['source_closure','protected_input_hashes','index_generated','bibliography_baseline']:
 for p,sha in b[key].items():assert h(M/p)==sha
for key in ['book_generated','index_configuration']:
 for p,sha in b[key].items():assert h(R/p)==sha
for v in b['prior_frozen_manifests']+b['prior_frozen_exports']:
 p=Path(v['path']);p=p if p.is_absolute() else R/p;assert h(p)==v['sha256'] and p.stat().st_size==v['bytes']
for k in ['source','PDF']:assert h(R/b['native_catalogue_reuse'][k]['path'])==b['native_catalogue_reuse'][k]['sha256']
assert h(M/'book.pdf')=='8a4e2770e77b6848d53482ac11d0e4561016d6f31cfc7588b22aebe4539c89d0'
fps=[C/'actual_main_reading_v1_20261007.json']+[C/f'actual_dependency_reading_v{i}_20261007.json' for i in range(1,5)]
frozen=[{'record':pin(p),'content':read(p)} for p in fps];inv={};seen=set();sheets=0
for fr in frozen:
 d=fr['content'];assert d['all_complete_selected_text_read'] and d['all_matching_images_individually_displayed'] and not d['identity_reuse'];sheets+=d['sheets']
 if 'notes_path' in d:
  np=Path(d['notes_path']);assert h(np)==d['notes_sha256'];fr['notes']=read(np)
 else:
  np=Path(d['sequential_notes']['path']);assert h(np)==d['sequential_notes']['sha256'];fr['notes']=read(np)
 assert len(fr['notes'])==d['sheets']
 for v in d['actual_views']:
  assert v['actually_viewed'] and v['selected_text_read'] and v['reading_note']
  for path,key in [('source_PDF_path','source_PDF_sha256'),('path','image_sha256'),('selected_text_path','selected_text_sha256')]:assert h(v[path])==v[key]
  k=v['source_PDF_sha256'];r=inv.setdefault(k,{'source':v['source'],'PDF':pin(Path(v['source_PDF_path'])),'PDF_pages':len(fitz.open(v['source_PDF_path'])),'actual_pages':set()})
  for n in v['physical_pages']:assert (k,n) not in seen;seen.add((k,n));r['actual_pages'].add(n)
for r in inv.values():r['actual_pages']=sorted(r['actual_pages']);r['whole_PDF_actually_read']=r['actual_pages']==list(range(1,r['PDF_pages']+1))
assert len(seen)==131 and sheets==70 and len(inv)==13 and sum(r['whole_PDF_actually_read'] for r in inv.values())==5
acs=[C/'acquisition_v1_20261007.json']+[C/f'dependency_acquisition_v{i}_20261007.json' for i in range(1,4)]
acqs=[{'record':pin(p),'content':read(p)} for p in acs]
for a in acqs:
 for r in a['content']['records']:
  if r.get('acquired'):assert h(r['path'])==r['sha256']
hp=C/'arxiv_CidRuiz_SegreClasses_history.html';ht=hp.read_text();assert '9 Dec 2025 17:54:09 UTC' in ht and '18 Jun 2026 13:43:04 UTC' in ht
audit=M/'editorial/Segre_finite_pullback_source_review_20261007.md'
rec={'recorded_UTC':datetime.datetime.now(datetime.timezone.utc).isoformat(),'baseline_record':pin(bp),'baseline_commit':b['baseline_commit'],'observed_origin_main':b['origin_main'],'source_only':True,'actual_distinct_source_page_pairs':131,'individually_displayed_sheets':70,'PDFs_read_in_exact_scopes':13,'complete_PDFs':5,'partial_PDFs':8,'identity_reuse':False,'source_inventory':list(inv.values()),'acquisitions':acqs,'actual_frozen_reading_records':frozen,'metadata_only_CidRuiz_arxiv_history':{'record':pin(hp),'v1_submitted_UTC':'2025-12-09T17:54:09Z','v2_submitted_UTC':'2026-06-18T13:43:04Z','arxiv_PDF_acquired':False,'arxiv_PDF_read':False},'current_source_audit':pin(audit),'preservation':{'all_5197_tracked_baseline_hashes_match':True,'active_input_hashes':b['source_closure'],'protected_input_hashes':b['protected_input_hashes'],'prior_frozen_manifests':b['prior_frozen_manifests'],'prior_frozen_exports':b['prior_frozen_exports'],'book_generated':b['book_generated'],'index_generated':b['index_generated'],'index_configuration':b['index_configuration'],'native_catalogue':b['native_catalogue_reuse'],'bibliography_baseline':b['bibliography_baseline']},'all_original_dependency_proofs_recursively_certified':False,'new_book_compilation':False,'final_book_page_reading':False,'new_canonical_atomic_problem_added':False,'canonical_status_promoted':False,'original_result_admitted':False,'independent_model_receipt_created':False,'BJ22_general_Siu_repair_claimed':False,'helper_source':Path(__file__).read_text()}
out.write_text(json.dumps(rec,indent=2)+'\n');print(json.dumps({'manifest_sha256':h(out),'audit_sha256':h(audit),'page_pairs':131,'sheets':70,'complete_PDFs':5,'source_only':True,'preservation_pass':True,'bytes':out.stat().st_size}))
